-- The nameplate addon exercises a small, documented subset of the client's StatusBar
-- and CheckButton APIs. Keep these strict so missing game methods fail in the mock.
ENGINE_METHODS["StatusBar"] = {}
for k in pairs(ENGINE_METHODS["Frame"]) do ENGINE_METHODS["StatusBar"][k] = true end
for _, k in ipairs({ "GetMinMaxValues", "GetStatusBarColor", "GetStatusBarTexture", "GetValue",
	"SetMinMaxValues", "SetStatusBarColor", "SetStatusBarTexture", "SetValue" }) do
	ENGINE_METHODS["StatusBar"][k] = true
end

